/**
 * Copy the trained artifacts into `public/` so the static build can serve them.
 *
 * They are generated by `scripts/train_and_benchmark.py` and live in
 * `../artifacts`. Copying rather than committing a second time keeps one
 * source of truth: retrain, rebuild, and the dashboard picks up the new model
 * with no chance of the two versions disagreeing.
 */

import { copyFileSync, existsSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const artifacts = join(here, "..", "..", "artifacts");
const target = join(here, "..", "public");

const REQUIRED = ["model.json"];
const OPTIONAL = ["benchmark.json", "ablation.json"];

mkdirSync(target, { recursive: true });

for (const name of [...REQUIRED, ...OPTIONAL]) {
  const source = join(artifacts, name);
  if (!existsSync(source)) {
    if (REQUIRED.includes(name)) {
      console.error(
        `missing ${source}\nRun: python scripts/train_and_benchmark.py`,
      );
      process.exit(1);
    }
    console.warn(`skipping optional artifact ${name} (not generated yet)`);
    continue;
  }
  copyFileSync(source, join(target, name));
  console.log(`synced ${name}`);
}
